 9→    private int upgradeCost;
10→    private int level; // 0-3级，0表示未升级
11→    private Player owner;
12→    
13→    public PropertyCell(int id, String name, int basePrice, int baseRent, int upgradeCost) {
14→        super(id, name, CellType.PROPERTY);
15→        this.basePrice = basePrice;
16→        this.baseRent = baseRent;
17→        this.upgradeCost = upgradeCost;
18→        this.level = 0;
19→        this.owner = null;
20→    }
21→    
22→    @Override
23→    public void action(Player player) {
24→        if (owner == null) {
25→            // 无人拥有，可以购买
26→            System.out.println(player.getName() + " 停在未拥有的房产 " + getName());
27→        } else if (owner.equals(player)) {
28→            // 自己的房产，可以选择升级
29→            System.out.println(player.getName() + " 停在自己的房产 " + getName() + "，当前等级: " + level);
30→        } else {
31→            // 别人的房产，需要支付租金
32→            int rent = calculateRent();
33→            System.out.println(player.getName() + " 停在 " + owner.getName() + " 的房产 " + getName() + 
34→                             "，需要支付租金: " + rent);
35→            player.payMoney(rent);
36→            owner.receiveMoney(rent);
37→        }
38→    }
